/**
 * Market price verification gate.
 *
 * `price-verification.json` is generated by scripts/price-scan/scan.mjs from the
 * live price book. A market is verified only when its prices are its own and
 * fresh: FX-derived reference rows and stale rows both count against it. When a
 * market is not verified, calculators keep working but the page says so, because
 * quoting a local customer from reference prices without saying it is dishonest.
 */
import verification from "./price-verification.json";

export interface MarketPriceVerification {
  total: number;
  local_verified: number;
  fx_reference: number;
  stale: number;
  verified: boolean;
}

const MARKETS = (verification as { markets: Record<string, MarketPriceVerification> }).markets;

export const PRICE_VERIFICATION_SCANNED_AT = (verification as { scanned_at: string }).scanned_at;

export function getMarketPriceVerification(
  marketCode: string | null | undefined,
): MarketPriceVerification | null {
  if (!marketCode) return null;
  return MARKETS[marketCode] ?? null;
}

export function isMarketPriceVerified(marketCode: string | null | undefined): boolean {
  return getMarketPriceVerification(marketCode)?.verified === true;
}
